/* Subscription presentation settings never change eligibility, prices or reward rules. */
window.MioSubscriptions=(()=>{
 'use strict';
 const categories=[{id:'regular',name:'Regular Subscriptions',short:'Regular',icon:'layers'},{id:'platinum',name:'Platinum Subscription',short:'Platinum',icon:'diamond'},{id:'promotional',name:'Promotional Subscriptions',short:'Promotional',icon:'sparkle'}];
 const defaults={ADVANCED_2:['regular',1],ADVANCED_1:['regular',2],BASIC_2:['regular',3],PREMIUM:['platinum',1],BASIC_1:['promotional',1]};
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=id=>document.getElementById(id);
 let api=null,plans=[],display=[],selected='regular',menuOpen=false,navActive=false,loadTurn=0,displayReady=false,mobileCode=null;
 const icon=kind=>`<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">${kind==='diamond'?'<path d="M3 11l6-7h14l6 7-13 17zM3 11h26M9 4l7 24 7-24"/>':kind==='sparkle'?'<path d="M13 3l3 8 8 3-8 3-3 8-3-8-8-3 8-3zM25 21l1.5 4 4 1.5-4 1.5-1.5 4-1.5-4-4-1.5 4-1.5z"/>':'<path d="M3 10l13-7 13 7-13 7zM3 17l13 7 13-7M3 24l13 7 13-7"/>'}</svg>`;
 function setting(code){const row=display.find(x=>x.package_code===code);return row||{package_code:code,category:defaults[code]?.[0]||'regular',display_order:defaults[code]?.[1]||100,version:0}}
 function list(category){return plans.filter(p=>setting(p.code).category===category).sort((a,b)=>setting(a.code).display_order-setting(b.code).display_order||b.payable-a.payable||a.code.localeCompare(b.code))}
 function select(category,focus=false){mobileCode=null;selected=categories.some(c=>c.id===category)?category:'regular';render();syncNav();if(focus)$('subscriptionCategoryHeading')?.focus({preventScroll:true})}
 function syncNav(){document.querySelectorAll('[data-subscription-category]').forEach(b=>{const on=b.dataset.subscriptionCategory===selected&&(!b.closest('.subscription-nav')||navActive);b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});}
 function navigation(active){if(active&&!navActive)menuOpen=true;navActive=active;return `<div class="subscription-nav member-wallet-menu"><button type="button" data-subscription-menu aria-expanded="${menuOpen}" aria-controls="subscriptionNavOptions" class="member-wallet-toggle ${active?'wallet-current':''}">${icon('diamond')}<span>Subscription Plans</span><span class="wallet-menu-chevron" aria-hidden="true">⌄</span></button><div id="subscriptionNavOptions" class="subscription-nav-options member-wallet-submenu" ${menuOpen?'':'hidden'}>${categories.map(c=>`<button type="button" data-subscription-category="${c.id}" class="${active&&selected===c.id?'active':''}" ${active&&selected===c.id?'aria-current="page"':''}><span>${c.short}</span></button>`).join('')}</div></div>`}
 function toggleMenu(){menuOpen=!menuOpen;document.querySelectorAll('[data-subscription-menu]').forEach(b=>b.setAttribute('aria-expanded',String(menuOpen)));const options=$('subscriptionNavOptions');if(options)options.hidden=!menuOpen;}
 function current(){return plans.find(p=>p.code===api?.current?.())||null}
 function state(p){const active=current();return !active?'available':p.code===active.code?'current':Number(p.payable)<=Number(active.payable)?'lower':'available'}
 function blockPurchase(code){const plan=plans.find(p=>p.code===code),active=current();if(!plan||!active||state(plan)==='available')return false;
  const higher=plans.filter(p=>Number(p.payable)>Number(active.payable)).sort((a,b)=>a.payable-b.payable);
  window.MioActionConfirmation?.show({kind:'restriction',owner:api.owner(),plan:active.name,amount:active.payable,title:'Subscription already active',message:`Your ${active.name} subscription is active. You cannot purchase your current package again or choose a lower package. ${higher.length?'Please select a higher subscription to upgrade.':'You already have the highest subscription.'}`,upgrades:higher.map(p=>p.name).join(' or '),onUpgrade:higher.length?()=>{select(setting(higher[0].code).category,true);api.go('packages')}:null});return true;
 }
 function planCard(p){const sl=p.singleLevels||({BASIC_1:10,BASIC_2:15,ADVANCED_1:20,ADVANCED_2:25,PREMIUM:30}[p.code]),status=state(p),label=status==='current'?'Already active':status==='lower'?'Upgrade only':current()?'Upgrade to '+p.name:'Activate '+p.name;return `<article class="package ${p.code===mobileCode?'mobile-selected':''}" data-subscription-plan="${esc(p.code)}" data-plan-state="${status}"><div class="package-top"><div class="package-badges"><span class="pill">${p.code==='PREMIUM'?'MIO only':'MIO or shopping PPV'}</span>${status==='current'?'<span class="plan-status current">✓ Current plan</span>':status==='lower'?'<span class="plan-status lower">Lower plan</span>':''}</div><h3>${esc(p.name)}</h3></div><div class="pay">${esc(p.payable)} <small>MIO Points</small></div><p class="package-cost">${esc(p.base)} base + ${esc(p.fee)} company fee</p><dl><dt>Personal points · PPV</dt><dd>${esc(p.ppv)}</dd><dt>Bonus base · BV</dt><dd>${esc(p.bv)}</dd><dt>Direct bonus</dt><dd>${esc(p.direct)}%</dd><dt>Generation levels</dt><dd>${esc(p.generations)}</dd><dt>Binary placement levels</dt><dd>${esc(sl)}</dd><dt>Binary entitlement</dt><dd>${esc(p.entitlement)}%</dd></dl><details class="plain-details"><summary>All point allocations</summary><dl><dt>Direct points · DP</dt><dd>${esc(p.dp)}</dd><dt>Generation points · GP</dt><dd>${esc(p.gp)}</dd><dt>Binary points · BP</dt><dd>${esc(p.bp)}</dd><dt>Binary reference · BRP</dt><dd>${esc(p.brp)}</dd></dl></details><button type="button" class="btn activate-package ${status==='available'?'primary':'plan-locked'}" data-code="${esc(p.code)}">${status==='available'?'':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/></svg>'}${esc(label)}</button></article>`}
 function selectMobile(code){if(!list(selected).some(p=>p.code===code))return;mobileCode=code;render();$('subscriptionPlanTabs')?.querySelector(`[data-mobile-plan="${code}"]`)?.focus({preventScroll:true})}
 function render(next){if(next)plans=next;const grid=$('packageGrid');if(!grid)return;let controls=$('subscriptionCategories');if(!controls){controls=document.createElement('div');controls.id='subscriptionCategories';grid.before(controls)}const heading=$('page-packages')?.querySelector('.heading h1');if(heading){heading.id='subscriptionCategoryHeading';heading.tabIndex=-1;heading.textContent=categories.find(c=>c.id===selected).name}
  const items=list(selected),active=current();if(!items.some(p=>p.code===mobileCode))mobileCode=items[0]?.code;
  grid.classList.add('subscription-plan-grid');grid.hidden=false;
  controls.innerHTML=`<div class="subscription-toolbar"><label>Subscription category<select id="subscriptionCategorySelect">${categories.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.short}</option>`).join('')}</select></label></div>${active?`<p class="subscription-current">Current plan: <strong>${esc(active.name)} · ${esc(active.payable)} MIO</strong></p>`:''}<div id="subscriptionPlanTabs" class="subscription-mobile-tabs" aria-label="Choose a subscription" ${items.length<2?'hidden':''}>${items.map(p=>`<button type="button" data-mobile-plan="${p.code}" aria-pressed="${mobileCode===p.code}">${esc(p.name)}</button>`).join('')}</div>`;
  grid.dataset.count=String(items.length);grid.innerHTML=items.map(planCard).join('')||'<p class="empty">No subscriptions are currently listed in this category.</p>';
  let pager=$('subscriptionPlanPager');if(!pager){pager=document.createElement('div');pager.id='subscriptionPlanPager';grid.after(pager)}const i=items.findIndex(p=>p.code===mobileCode);pager.className='subscription-mobile-pager';pager.hidden=items.length<2;pager.innerHTML=`<button type="button" data-mobile-plan="${items[i-1]?.code||''}" ${i<=0?'disabled':''} aria-label="Previous package">‹</button><span aria-live="polite">${i+1} / ${items.length}</span><button type="button" data-mobile-plan="${items[i+1]?.code||''}" ${i>=items.length-1?'disabled':''} aria-label="Next package">›</button>`;
 }
 async function loadDisplay(){if(!api)return;const turn=++loadTurn;const r=await api.rpc('get_subscription_plan_display');if(turn!==loadTurn)return;if(r.error){displayReady=false;throw r.error}display=Array.isArray(r.data)?r.data:[];displayReady=true;render();}
 function renderAdmin(allPlans,code){plans=allPlans;const host=$('subscriptionDisplayAdmin');if(!host)return;const p=plans.find(p=>p.code===code)||plans[0];if(!p)return;const s=setting(p.code);host.innerHTML=`<div class="card-body"><div class="subscription-admin-heading"><div><span class="eyebrow">Subscription Plans</span><h2>Categories & display order</h2><p>Choose where each subscription appears.</p></div></div><div class="subscription-admin-layout"><div class="table-wrap"><table class="subscription-admin-table"><thead><tr><th>Plan</th><th>MIO Points</th><th>Category</th><th>Order</th><th></th></tr></thead><tbody>${categories.flatMap(c=>list(c.id).map(p=>`<tr><th scope="row">${esc(p.name)}</th><td>${esc(p.payable)}</td><td><span class="subscription-category-label ${c.id}">${c.name}</span></td><td>${setting(p.code).display_order}</td><td><button type="button" class="btn small" data-edit-subscription="${p.code}">Edit</button></td></tr>`)).join('')}</tbody></table></div><form id="subscriptionDisplayForm" class="form" data-code="${p.code}" data-version="${s.version}"><h3>Edit ${esc(p.name)}</h3><label>Subscription category<select name="category" required>${categories.map(c=>`<option value="${c.id}" ${c.id===s.category?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Display order<input name="display_order" type="number" min="1" max="9999" step="1" value="${s.display_order}" required></label><small>Lower numbers appear first within this category.</small><button type="submit" class="btn primary" ${displayReady?'':'disabled'}>Save category & order</button><p role="status" aria-live="polite">${displayReady?'':'Category settings could not be loaded. Reopen this page to retry.'}</p></form></div></div>`;}
 function mount(options){api=options;document.addEventListener('click',e=>{const mobile=e.target.closest('[data-mobile-plan]');if(mobile){selectMobile(mobile.dataset.mobilePlan);return}if(e.target.closest('[data-subscription-menu]')){toggleMenu();return}const category=e.target.closest('[data-subscription-category]');if(category){e.preventDefault();menuOpen=true;select(category.dataset.subscriptionCategory);api.go('packages');syncNav();$('subscriptionCategoryHeading')?.focus({preventScroll:true});return}if(e.target.closest('[data-subscription-home]')){select(null,true);return}const edit=e.target.closest('[data-edit-subscription]');if(edit){const picker=$('editPlanSelect');picker.value=edit.dataset.editSubscription;picker.dispatchEvent(new Event('change'));document.querySelector('#subscriptionDisplayForm select')?.focus();}});
  document.addEventListener('click',e=>{if(e.target.closest('[data-page="packages"]'))select(selected)},true);
  document.addEventListener('change',e=>{if(e.target.id==='subscriptionCategorySelect')select(e.target.value,true)});
  document.addEventListener('submit',async e=>{if(e.target.id!=='subscriptionDisplayForm')return;e.preventDefault();const f=e.target,b=f.querySelector('button[type="submit"]'),status=f.querySelector('[role="status"]');if(b.disabled)return;b.disabled=true;const owner=api.owner();try{if(!api.isAdmin())throw Error('Admin access required');const code=f.dataset.code,category=f.elements.category.value,order=Number(f.elements.display_order.value);if(!Number.isInteger(order)||order<1||order>9999)throw Error('Enter a display order from 1 to 9999.');await api.confirm('Save subscription category and display order.');if(owner!==api.owner())throw Error('Account changed. Please reopen the editor.');const r=await api.rpc('admin_set_subscription_plan_display',{p_code:code,p_category:category,p_display_order:order,p_expected_version:Number(f.dataset.version)});if(r.error)throw r.error;await loadDisplay();renderAdmin(plans,code);document.querySelector('#subscriptionDisplayForm [role="status"]').textContent='Category and display order saved.';}catch(error){status.textContent=error.message||'Category settings could not be saved.'}finally{b.disabled=false}});
 }
 return {mount,render,select,blockPurchase,state,navigation,loadDisplay,renderAdmin,setting,categories,get selected(){return selected}};
})();
